run('''
package main
import ("example.com/wtprobe/bar"; "errors"; "fmt")
func f1() error { var err error; err = bar.Do(); return err }
func f2() error { err := bar.Do(); err = errors.New("x"); return err }
func f3() error { err := errors.New("x"); err = bar.Do(); return err }
func f4() error { if err := bar.Do(); err != nil { return err }; return nil }
func f5() error { err := bar.Do(); if err != nil { return err }; return nil }
func f6() error { var err error; return err }
func f7() error { err := bar.Do(); _ = err; return nil }
func f8() error { x := bar.Do(); return x }
func f9() error { err, _ := func() (error, int){ return bar.Do(), 0 }(); return err }
func f10() error { err := func() error { return bar.Do() }(); return err }
func f11() error { fn := bar.Do; return fn() }
func f12() error { fn := bar.Do; err := fn(); return err }
func main(){}
''')

run('''
package main
import ("example.com/wtprobe/bar"; "errors"; "fmt")
func f1() error {
  err := bar.Do()
  err2 := err
  return err2
}
func f2() error {
  err := bar.Do()
  wrapped := fmt.Errorf("w: %w", err)
  return wrapped
}
func f3() error {
  err := bar.Do()
  wrapped := errors.Join(err)
  return wrapped
}
func f4() error {
  _, err := bar.Do2()
  return err
}
func f5() (err error) {
  err = bar.Do()
  return
}
func f6() (err error) {
  err = bar.Do()
  return err
}
func f7() error {
  var err error
  _, err = bar.Do2()
  return err
}
func main(){}
''')

