import ("example.com/wtprobe/bar"; "errors")
func f1() error {
  err := bar.Do()
  if true {
    err := errors.New("inner")
    return err
  }
  return err
}
func f2() error {
  err := errors.New("outer")
  if true {
    err := bar.Do()
    return err
  }
  return err
}
func f3() error {
  err := bar.Do()
  // reassign in branch
  if true { err = errors.New("branch") }
  return err
}
func f4() error {
  err := errors.New("x")
  if true { err = bar.Do() }
  return err
}
