	}
}

func isInterfaceType(typ types.Type) bool {
	for typ != nil {
		if _, ok := typ.Underlying().(*types.Interface); ok {
			return true
		}
		pointer, ok := typ.Underlying().(*types.Pointer)
		if !ok {
			return false
		}
		typ = pointer.Elem()
	}
	return false
}

func packageNameQualifier(pkg *types.Package) string {
	if pkg == nil {
		return ""
	}
	return pkg.Name()
}

func classifyCall(pass *analysis.Pass, cc *compiledConfig, call *ast.CallExpr, obj types.Object) int {
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		// A plain identifier is treated as a call within the package being
		// analysed, even where the identifier was dot-imported.
		return sourceInternal
	case *ast.SelectorExpr:
		pkgPath := ""
		if obj != nil && obj.Pkg() != nil {
			pkgPath = obj.Pkg().Path()
		}

		for _, g := range cc.packageGlobs {
			if g.Match(pkgPath) {
				return sourceInternal
			}
		}

		if sel := pass.TypesInfo.Selections[fun]; sel != nil && isInterfaceType(sel.Recv()) {
			ifaceName := types.TypeString(sel.Recv(), packageNameQualifier)
			ignored := false
			for _, re := range cc.interfaceRegexps {
				if re.MatchString(ifaceName) {
					ignored = true
					break
				}
			}
			if !ignored {
				return sourceInterface
			}
			// Ignoring the interface only removes the special interface
			// classification. The package of the called object decides
			// between the ordinary internal and external cases below.
		}

		if pass.Pkg == nil || pkgPath == pass.Pkg.Path() || pkgPath == "" {
			return sourceInternal
		}
		return sourceExternal
	default:
		return sourceInternal
	}
}

func reportUnwrapped(pass *analysis.Pass, cc *compiledConfig, call *ast.CallExpr, pos token.Pos) {
	obj := calledObject(pass, call)
	if obj == nil {
		return
	}

	sig := obj.String()
	for _, ignored := range cc.cfg.IgnoreSigs {
		if strings.Contains(sig, ignored) {
			return
		}
	}
	for _, re := range cc.sigRegexps {
		if re.MatchString(sig) {
			return
		}
	}

	switch classifyCall(pass, cc, call, obj) {
	case sourceInterface:
		pass.Report(analysis.Diagnostic{
			Pos:     pos,
			Message: fmt.Sprintf("error returned from interface method should be wrapped: sig: %s", sig),
		})
	case sourceExternal:
		pass.Report(analysis.Diagnostic{
			Pos:     pos,
			Message: fmt.Sprintf("error returned from external package is unwrapped: sig: %s", sig),
		})
	case sourceInternal:
		if cc.cfg.ReportInternalErrors {
			pass.Report(analysis.Diagnostic{
				Pos:     pos,
				Message: fmt.Sprintf("package-internal error should be wrapped: sig: %s", sig),
			})
		}
	}
}
